import json, re, sys

src, dst = sys.argv[1], sys.argv[2]
EMAIL = re.compile(r"[A-Za-z0-9._+-]+@gmail\.com")
REMINDER = re.compile(r"<system-reminder>.*?</system-reminder>", re.S)
PASTE_TAG = re.compile(r"</?pasted_content[^>]*>")
MAX_RESULT = 1500


def clean(s):
    s = REMINDER.sub("", s)
    s = PASTE_TAG.sub("", s)
    s = EMAIL.sub("[email redacted]", s)
    return s.strip()


def text_of(content):
    if isinstance(content, str):
        return clean(content)
    out = []
    for b in content:
        if not isinstance(b, dict):
            continue
        t = b.get("type")
        if t == "text":
            out.append(clean(b.get("text", "")))
        elif t == "image":
            out.append("[image]")
    return "\n\n".join(x for x in out if x)


def result_text(content):
    if isinstance(content, list):
        content = "\n".join(b.get("text", "") for b in content if isinstance(b, dict))
    s = clean(str(content))
    if len(s) > MAX_RESULT:
        s = s[:MAX_RESULT] + "\n... [truncated]"
    return s


parts = ["# Claude Code session: running the RTX 4090 runbook\n"]
with open(src, encoding="utf-8") as f:
    for line in f:
        d = json.loads(line)
        t = d.get("type")
        m = d.get("message")
        if t not in ("user", "assistant") or not isinstance(m, dict):
            continue
        content = m.get("content")
        if t == "user":
            if isinstance(content, list) and content and all(
                isinstance(b, dict) and b.get("type") == "tool_result" for b in content
            ):
                for b in content:
                    parts.append("**Tool result:**\n```\n" + result_text(b.get("content", "")) + "\n```\n")
                continue
            txt = text_of(content)
            if txt:
                parts.append("## User\n\n" + txt + "\n")
        else:
            for b in content if isinstance(content, list) else []:
                if b.get("type") == "text":
                    txt = clean(b.get("text", ""))
                    if txt:
                        parts.append("## Assistant\n\n" + txt + "\n")
                elif b.get("type") == "tool_use":
                    inp = json.dumps(b.get("input", {}), ensure_ascii=False)
                    inp = EMAIL.sub("[email redacted]", inp)
                    if len(inp) > MAX_RESULT:
                        inp = inp[:MAX_RESULT] + " ... [truncated]"
                    parts.append(f"**Tool call: {b.get('name')}**\n```\n{inp}\n```\n")

with open(dst, "w", encoding="utf-8", newline="\n") as f:
    f.write("\n".join(parts))
print("written", dst, sum(len(p) for p in parts), "chars")

